    @Test
    void modifyingStartedHourReturns409WhileFutureHoursCanChangeAndSnapshotKept() throws Exception {
        long windowId = createHourlyWindow("ch-started-" + run, "20");
        clock.fixedAt(Instant.parse("2026-11-30T12:00:00Z"));
